    const closes = ratio !== null && ratio <= 1;
    const xiHalfWidth = Array.isArray(rowContext?.xi_interval)
      ? intervalWidth(rowContext.xi_interval) / 2
      : null;
    const numeratorRemainderAbsUpper =
      n38D4AbsUpper === null
