              terminalRowChecks,
            terminal_successor_coefficient_identity_imported_for_h39_node:
              importedForNode,
            row_certifies_terminal_successor_coefficient_identity_import:
              false,
            row_certifies_terminal_successor_scalar_residual_identity: false,
            row_status: importedForNode
