    "branch_identity_terminal_rows_available",
    "same_domain_terminal_rows_aligned",
    "branch_split_linear_system_rank_recorded",
    "canonical_symmetric_split_sums_to_aggregate",
    "branch_antisymmetric_coordinate_recorded_free",
    "centered_residual_branch_split_recorded_open",
    "h39_broad_claims_remain_open",
