    "branch_composition_terminal_row_available",
    "aggregate_centered_residual_available",
    "branch_unknown_rows_declared",
    "branch_split_linear_system_rank_recorded",
    "canonical_symmetric_split_sums_to_aggregate",
    "branch_antisymmetric_coordinate_recorded_free",
    "same_domain_terminal_row_aligned",
    "composition_identity_recorded_open",
    "h39_claims_remain_open",
