  targetSpeedInterval = [3.02156, 3.02156007813],
  branch = "-",
  rootSubdivisions = 100,
  outerRadius = 0.001,
  shiftedIndex = 1,
  seriesOrder = 60,
  xiDomain = [-2, 2],
